    "texte": "La {1} par les coûts fait du prix de vente l'avantage concurrentiel, sur une cible large. La {2} consiste à proposer un produit qui paraît {3} aux yeux des consommateurs. La {4}, ou focalisation, développe un avantage sur un segment étroit, une {5}.",
